:root {
  /* Colors */
  --color-signal-indigo: #4457ff;
  --color-cobalt-link: #394be0;
  --color-paper-canvas: #ffffff;
  --color-mist-surface: #f5f5f8;
  --color-linen-button: #f4f2f0;
  --color-graphite-ink: #23252b;
  --color-iron-nav: #4f5562;
  --color-slate-body: #666c77;
  --color-pewter-caption: #7d8290;
  --color-ash-border: #d8dbe2;
  --color-sky-ring: #84a1ff;
  --color-sky-badge: #5a84ff;
  --color-frost-tint: #eef2ff;

  /* Typography — Font Families */
  --font-plus-jakarta-sans: "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-sometype-mono: "Sometype Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.5;
  --tracking-small: 1.1px;
  --text-caption: 12px;
  --leading-caption: 1.2;
  --tracking-caption: -0.24px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.54;
  --tracking-body-sm: -0.13px;
  --text-body: 14px;
  --leading-body: 1.5;
  --tracking-body: -0.28px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: -0.416px;
  --text-subheading: 18px;
  --leading-subheading: 1.5;
  --tracking-subheading: -0.63px;
  --text-heading-sm: 21px;
  --leading-heading-sm: 1.5;
  --tracking-heading-sm: -0.672px;
  --text-heading: 36px;
  --leading-heading: 1.05;
  --tracking-heading: -1.08px;
  --text-heading-lg: 55px;
  --leading-heading-lg: 1.02;
  --tracking-heading-lg: -1.925px;
  --text-display: 58px;
  --leading-display: 0.98;
  --tracking-display: -1.74px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-46: 46px;
  --spacing-64: 64px;
  --spacing-136: 136px;

  /* Layout */
  --layout-page-max-width: 1188px;
  --layout-section-gap: 136px;
  --layout-card-padding: 32px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 11px;
  --radius-lg: 12px;
  --radius-xl: 15px;
  --radius-2xl: 22px;
  --radius-3xl: 28px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 28px;
  --radius-small-cards: 22px;
  --radius-images: 22px;
  --radius-buttons: 15px;
  --radius-inner-tiles: 12px;
  --radius-nav: 11px;
  --radius-small-elements: 8px;
  --radius-pills: 9999px;
  --radius-tags: 9999px;
  --radius-badges: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: inset 0 1px 0 0 rgba(255, 255, 255, 0.7);
  --shadow-lg: 0 24px 60px 0 rgba(66, 74, 119, 0.08);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-mist-surface: #f5f5f8;
  --surface-linen-button: #f4f2f0;
  --surface-frost-tint: #eef2ff;
  --surface-signal-indigo: #4457ff;
}

